BEGIN;
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_sessions (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,jti CHAR(36) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,last_activity_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,idle_expires_at TIMESTAMP NOT NULL,absolute_expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP NULL);
CREATE INDEX IF NOT EXISTS idx_session_user ON auth_sessions(user_id);
CREATE TABLE IF NOT EXISTS plans (id BIGSERIAL PRIMARY KEY,owner_id BIGINT REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',start_date DATE NOT NULL,end_date DATE NOT NULL,priority VARCHAR(10) NOT NULL CHECK(priority IN ('low','medium','high')),success_criteria TEXT NOT NULL,estimated_minutes INTEGER NOT NULL DEFAULT 0 CHECK(estimated_minutes>=0),carried_improvement TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_plan_owner ON plans(owner_id);
CREATE TABLE IF NOT EXISTS plan_history (history_id BIGSERIAL PRIMARY KEY,plan_id BIGINT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,title VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',start_date DATE NOT NULL,end_date DATE NOT NULL,priority VARCHAR(10) NOT NULL,success_criteria TEXT NOT NULL,estimated_minutes INTEGER NOT NULL,carried_improvement TEXT,saved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tasks (id BIGSERIAL PRIMARY KEY,plan_id BIGINT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,title VARCHAR(255) NOT NULL,description TEXT NOT NULL DEFAULT '',due_date DATE NOT NULL,priority VARCHAR(10) NOT NULL CHECK(priority IN ('low','medium','high')),tag VARCHAR(100),estimated_minutes INTEGER NOT NULL DEFAULT 0 CHECK(estimated_minutes>=0),status VARCHAR(20) NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','completed')),completed_at TIMESTAMP,deleted_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS execution_logs (id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,start_time TIMESTAMP NOT NULL,end_time TIMESTAMP NOT NULL,actual_minutes INTEGER NOT NULL CHECK(actual_minutes>=0),blocker_reason TEXT,work_done TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS task_completion_events (id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,completion_key VARCHAR(100) NOT NULL UNIQUE,completed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reflections (id BIGSERIAL PRIMARY KEY,plan_id BIGINT NOT NULL REFERENCES plans(id) ON DELETE CASCADE,improvement TEXT NOT NULL,carried_to_plan_id BIGINT REFERENCES plans(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_records (id BIGSERIAL PRIMARY KEY,owner_id BIGINT REFERENCES users(id) ON DELETE CASCADE,record_date DATE NOT NULL,metric_name VARCHAR(120) NOT NULL,metric_unit VARCHAR(40) NOT NULL,metric_value NUMERIC(12,2),calculation_rule TEXT NOT NULL,plan_rule TEXT NOT NULL,note TEXT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(owner_id,record_date));
CREATE TABLE IF NOT EXISTS rule_changes (id BIGSERIAL PRIMARY KEY,owner_id BIGINT UNIQUE REFERENCES users(id) ON DELETE CASCADE,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,before_rule TEXT NOT NULL,after_rule TEXT NOT NULL,reason TEXT NOT NULL,day1_record_id BIGINT NOT NULL REFERENCES daily_records(id) ON DELETE CASCADE,day2_record_id BIGINT NOT NULL REFERENCES daily_records(id) ON DELETE CASCADE);
COMMIT;
